package com.danawa.search.analysis.dict

import com.danawa.io.InputStreamDataInput
import com.danawa.io.OutputStreamDataOutput
import com.danawa.util.CharVector
import java.io.*
import java.util.Collections
import java.util.HashMap

open class MapDictionary : SourceDictionary<Any> {

    protected var map: MutableMap<CharSequence, Array<CharSequence>>

    constructor() : this(false)

    constructor(ignoreCase: Boolean) : super(ignoreCase, null, 0, null, ProductNameDictionary.Type.MAP) {
        map = HashMap()
    }

    constructor(map: MutableMap<CharSequence, Array<CharSequence>>, ignoreCase: Boolean, label: String?, seq: Int, tokenType: String?, type: ProductNameDictionary.Type)
            : super(ignoreCase, label, seq, tokenType, type) {
        this.map = map
    }

    constructor(file: File, ignoreCase: Boolean, label: String?, seq: Int, tokenType: String?, type: ProductNameDictionary.Type)
            : super(ignoreCase, label, seq, tokenType, type) {
        if (!file.exists()) {
            map = HashMap()
            logger.error("사전파일이 존재하지 않습니다. file={}", file.absolutePath)
            return
        }
        var `is`: InputStream? = null
        try {
            `is` = FileInputStream(file)
            readFrom(`is`)
        } catch (e: IOException) {
            logger.error("", e)
        } finally {
            try { `is`?.close() } catch (ignore: Exception) { }
        }
    }

    constructor(`is`: InputStream, ignoreCase: Boolean, label: String?, seq: Int, tokenType: String?, type: ProductNameDictionary.Type)
            : super(ignoreCase, label, seq, tokenType, type) {
        map = HashMap()
        try {
            readFrom(`is`)
        } catch (e: IOException) {
            logger.error("", e)
        }
    }

    override fun addEntry(keyword: CharSequence?, values: Array<Any>?, columnSettingList: List<Any>?) {
        if (keyword == null) return
        if (values == null) return
        val cv = CharVector(keyword.toString().trim(), ignoreCase)
        if (cv.length() == 0) return
        val list = Array<CharSequence>(values.size) { CharVector(values[it].toString(), ignoreCase) }
        map[cv.removeWhitespaces()] = list
    }

    fun getUnmodifiableMap(): Map<CharSequence, Array<CharSequence>> = Collections.unmodifiableMap(map)

    fun map(): MutableMap<CharSequence, Array<CharSequence>> = map

    fun setMap(map: MutableMap<CharSequence, Array<CharSequence>>) { this.map = map }

    fun containsKey(key: CharSequence): Boolean = map.containsKey(key)

    operator fun get(key: CharSequence): Array<CharSequence>? = map[key]

    @Throws(IOException::class)
    override fun writeTo(out: OutputStream) {
        var outputStream = out
        if (outputStream !is BufferedOutputStream) {
            try { outputStream = BufferedOutputStream(outputStream) } catch (ignore: Exception) { }
        }
        val output = OutputStreamDataOutput(outputStream)
        val keySet = map.keys.iterator()
        output.writeVInt(map.size)
        while (keySet.hasNext()) {
            val key = CharVector.valueOf(keySet.next())!!
            output.writeUString(key.array(), key.offset(), key.length())
            val values = map[key]!!
            output.writeVInt(values.size)
            for (v in values) {
                val value = CharVector.valueOf(v)!!
                output.writeUString(value.array(), value.offset(), value.length())
            }
        }
        try { outputStream.flush() } catch (ignore: Exception) { }
    }

    @Throws(IOException::class)
    override fun readFrom(`in`: InputStream) {
        var inputStream = `in`
        if (inputStream !is BufferedInputStream) {
            try { inputStream = BufferedInputStream(inputStream) } catch (ignore: Exception) { }
        }
        val input = InputStreamDataInput(inputStream)
        map = HashMap()
        val size = input.readVInt()
        for (entryInx in 0 until size) {
            val key: CharSequence = CharVector(input.readUString(), ignoreCase)
            val valueLength = input.readVInt()
            val values = Array<CharSequence>(valueLength) { CharVector(input.readUString(), ignoreCase) }
            map[key] = values
        }
    }

    override fun addSourceLineEntry(line: CharSequence) {
        if (line == null) return
        val kv = line.toString().split("\t")
        if (kv.size == 1) {
            val value = kv[0].trim()
            addEntry(null, arrayOf(value), null)
        } else if (kv.size == 2) {
            val keyword = kv[0].trim()
            val value = kv[1].trim()
            addEntry(keyword, arrayOf(value), null)
        }
    }

    override fun reload(`object`: Any?) {
        if (`object` != null && `object` is MapDictionary) {
            this.map = `object`.map()
        } else {
            throw IllegalArgumentException("Reload dictionary argument error. argument = $`object`")
        }
    }
}

